targets.expr:
sum(
  rate({service="nginx", env="$env", host="$host", log_type="access"}[$__interval])
) * 60

quantile_over_time(
  0.95,
  {service="nginx", env="$env", host="$host", log_type="access"}
    | unwrap request_time
  [$__interval]
) by (host)

sum(
  rate({service="nginx", env="$env", log_type="error"}[$__interval])
) * 60

sum(
  rate(
    {service="nginx", env="$env", host="$host", log_type="access"}
      | unwrap bytes_sent
    [$__interval]
  )
)

sum(
  rate({service="nginx", env="$env", host="$host", log_type="access", status=~"2.."}[$__interval])
) * 60

sum(
  rate({service="nginx", env="$env", host="$host", log_type="access", status=~"3.."}[$__interval])
) * 60

sum(
  rate({service="nginx", env="$env", host="$host", log_type="access", status="404"}[$__interval])
) * 60

sum(
  rate({service="nginx", env="$env", host="$host", log_type="access", status=~"4..", status!="404", status!="429", status!="499"}[$__interval])
) * 60

sum(
  rate({service="nginx", env="$env", host="$host", log_type="access", status="429"}[$__interval])
) * 60

sum(
  rate({service="nginx", env="$env", host="$host", log_type="access", status="499"}[$__interval])
) * 60

sum(
  rate({service="nginx", env="$env", host="$host", log_type="access", status=~"5.."}[$__interval])
) * 60

quantile_over_time(
  0.50,
  {service="nginx", env="$env", host="$host", log_type="access"}
    | unwrap request_time
  [$__interval]
) by (host)

quantile_over_time(
  0.75,
  {service="nginx", env="$env", host="$host", log_type="access"}
    | unwrap request_time
  [$__interval]
) by (host)

quantile_over_time(
  0.95,
  {service="nginx", env="$env", host="$host", log_type="access"}
    | unwrap request_time
  [$__interval]
) by (host)

quantile_over_time(
  0.99,
  {service="nginx", env="$env", host="$host", log_type="access"}
    | unwrap request_time
  [$__interval]
) by (host)

topk(
  12,
  sum by (section) (
    rate(
      {service="nginx", env="$env", host="$host", log_type="access", status!="404"}
        | section != ""
      [$__interval]
    )
  )
) * 60

sum(
  rate(
    {service="nginx", env="$env", host="$host", log_type="access", status="404"}[$__interval]
  )
) * 60

sum(
  rate({service="nginx", env="$env", host="$host", log_type="access"}
    | cf_ray = ""
  [$__interval])
) * 60

sum(
  rate({service="nginx", env="$env", host="$host", log_type="access"}
    | cf_ray != ""
  [$__interval])
) * 60

sum(
  rate({service="nginx", env="$env", host="$host", log_type="access"}
    | unwrap bytes_sent
  [$__interval])
)

topk(
  20,
  sum by (uri) (
    count_over_time({service="nginx", env="$env", host="$host", log_type="access", status="404"}[$__range])
  )
)

topk(
  20,
  sum by (user_agent) (
    count_over_time({service="nginx", env="$env", host="$host", log_type="access", status="404"}[$__range])
  )
)

topk(
  20,
  sum by (cf_ipcountry) (
    count_over_time({service="nginx", env="$env", host="$host", log_type="access"}[$__range])
  )
)

sum(
  rate({service="nginx", env="$env", host="$host", log_type="access"}
    | user_agent =~ "(?i).*(?:bot|spider|crawl|slurp|archiver|fetch|monitor|check|scrap).*"
  [$__interval])
) * 60

sum(
  rate({service="nginx", env="$env", host="$host", log_type="access"}
    | user_agent =~ "(?i).*(?:wget|curl|python|php).*"
  [$__interval])
) * 60

sum(
  rate({service="nginx", env="$env", host="$host", log_type="access"}
    | cf_verified_bot = "true"
  [$__interval])
) * 60

topk(
  10,
  sum by (search_engine) (
    rate(
      {service="nginx", env="$env", host="$host", log_type="access"}
        | search_engine != ""
      [$__interval]
    )
  )
) * 60

topk(
  10,
  sum by (ai_bot) (
    rate(
      {service="nginx", env="$env", host="$host", log_type="access"}
        | ai_bot != ""
      [$__interval]
    )
  )
) * 60

sum by (status) (
  rate({service="nginx", env="$env", host="$host", log_type="access", status=~"5.."}[$__interval])
) * 60

topk(
  8,
  sum by (message) (
    rate({service="nginx", env="$env", log_type="error"}[$__interval])
  )
) * 60
